package com.transportlogistics.app.tracking.domain.routedeviation;
import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class RouteDeviationRuleAndPositionTest {
 @Test void ruleLifecycleToleranceAndAccuracyAreExact(){UUID id=UUID.randomUUID();RouteDeviationRule r=new RouteDeviationRule(id,UUID.randomUUID(),UUID.randomUUID(),new RouteVersion("REVISION:1"),new DistanceMeters(BigDecimal.TEN),RouteDeviationRule.Lifecycle.DRAFT,0,0,null);r=r.activate(Instant.EPOCH);assertEquals(1,r.ruleVersion());assertFalse(r.editable());RouteDeviationRule active=r;assertThrows(RouteDeviationException.class,()->active.update(DistanceMeters.of(20)));r=r.disable().update(DistanceMeters.of(5000));assertEquals(new BigDecimal("5000.0"),r.configuredTolerance().value());assertThrows(RouteDeviationException.class,()->new RouteDeviationRule(id,UUID.randomUUID(),UUID.randomUUID(),new RouteVersion("REVISION:1"),DistanceMeters.of(9),RouteDeviationRule.Lifecycle.DRAFT,0,0,null));}
 @Test void eligibilityAndEffectiveTolerance(){Instant now=Instant.parse("2026-01-01T00:05:00Z");RouteDeviationPosition p=position(now.minusSeconds(300),DistanceMeters.of(1000),false,RouteDeviationPosition.Trust.TRUSTED,true,RouteDeviationPosition.Ordering.IN_ORDER);assertTrue(p.eligible(now));RouteDeviationRule r=new RouteDeviationRule(UUID.randomUUID(),p.tenantId(),UUID.randomUUID(),new RouteVersion("REVISION:1"),DistanceMeters.of(10),RouteDeviationRule.Lifecycle.ACTIVE,1,1,now);assertEquals(1010d,p.effectiveTolerance(r).value().doubleValue());assertFalse(position(now.minusSeconds(301),DistanceMeters.of(1),false,RouteDeviationPosition.Trust.TRUSTED,true,RouteDeviationPosition.Ordering.IN_ORDER).eligible(now));assertFalse(position(now,DistanceMeters.of(1001),false,RouteDeviationPosition.Trust.TRUSTED,true,RouteDeviationPosition.Ordering.IN_ORDER).eligible(now));}
 private static RouteDeviationPosition position(Instant t,DistanceMeters a,boolean dup,RouteDeviationPosition.Trust trust,boolean assoc,RouteDeviationPosition.Ordering order){return new RouteDeviationPosition(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),t,new RoutePoint(BigDecimal.ZERO,BigDecimal.ZERO),a,true,dup,trust,assoc,order);}
}
